insert into public.problems (id, title, statement, input_spec, output_spec, notes, examples, tags, rating, time_limit_ms, visibility) values (1223, 'Friend Groups', 'There are n birds and, at first, no friendships. Then q friendships appear one by one. After each new friendship, print how many friend groups there are. Two birds are in the same group if they are connected by a chain of friendships.', 'The first line contains n and q (1 ≤ n, q ≤ 2·10^4). Each of the next q lines contains a and b (1 ≤ a, b ≤ n). A friendship may repeat, and a may be equal to b.', 'Print q lines: the number of groups after each friendship.', '', '[{"input":"4 3\n1 2\n3 4\n2 1\n","output":"3\n2\n2"},{"input":"3 2\n1 1\n1 3\n","output":"3\n2"}]'::jsonb, array['dsu','graphs']::text[], 1600, 2000, 'public') on conflict (id) do nothing;
