insert into public.problems (id, title, statement, input_spec, output_spec, notes, examples, tags, rating, time_limit_ms, visibility) values (1226, 'Course Order', 'There are n courses, numbered from 1 to n, and m rules of the form "course a must be taken before course b". Find an order in which to take all the courses that respects every rule. If there are several such orders, print the one that is smallest in dictionary order (compare the first course, then the second, and so on). If no order exists, print `IMPOSSIBLE`.', 'The first line contains n and m (1 ≤ n ≤ 2·10^4, 0 ≤ m ≤ 2·10^4). Each of the next m lines contains a and b (1 ≤ a, b ≤ n, a ≠ b).', 'Print n course numbers separated by spaces, or `IMPOSSIBLE`.', '', '[{"input":"4 3\n2 1\n3 1\n4 3\n","output":"2 4 3 1"},{"input":"2 2\n1 2\n2 1\n","output":"IMPOSSIBLE"}]'::jsonb, array['graphs','topological sort','data structures']::text[], 1700, 2000, 'public') on conflict (id) do nothing;
